const ink = Color(0xFF0B0A10), panel = Color(0xFF15131D), violet = Color(0xFF9B72F2), muted = Color(0xFF9692A2);
const apiBase = String.fromEnvironment('API_BASE_URL', defaultValue: 'http://10.0.2.2:8000/api/v1');
const storage = FlutterSecureStorage();

class Drama {
  const Drama({required this.id, required this.title, required this.synopsis, required this.poster, required this.banner, required this.categories, this.rating, this.year});
  final int id; final String title, synopsis, poster, banner; final List<String> categories; final double? rating; final int? year;
  factory Drama.fromJson(Map<String,dynamic> j) => Drama(id:j['id'],title:j['title'],synopsis:j['synopsis']??'',poster:j['poster_url']??'',banner:j['banner_url']??'',categories:List<String>.from(j['categories']??[]),rating:(j['rating'] as num?)?.toDouble(),year:j['release_year']);
}
class ApiClient {
  Future<List<Drama>> dramas() async {
    final token = await storage.read(key:'access_token');
    final response = await http.get(Uri.parse('$apiBase/dramas?limit=50'),headers:token==null?{}:{'Authorization':'Bearer $token'}).timeout(const Duration(seconds:12));
    if(response.statusCode!=200) throw Exception('Catalogue indisponible (${response.statusCode})');
    return (jsonDecode(response.body) as List).map((e)=>Drama.fromJson(e)).toList();
  }
  Future<void> _saveTokens(http.Response r) async {
    if(r.statusCode<200||r.statusCode>=300) throw Exception('Authentification refusée (${r.statusCode})');
    final data=jsonDecode(r.body); await storage.write(key:'access_token',value:data['access_token']); await storage.write(key:'refresh_token',value:data['refresh_token']);
  }
  Future<void> login(String email,String password) async {
    final r=await http.post(Uri.parse('$apiBase/auth/login'),headers:{'Content-Type':'application/json'},body:jsonEncode({'email':email,'password':password})).timeout(const Duration(seconds:12));
    await _saveTokens(r);
  }
  Future<void> register(String name,String email,String password) async {
    final r=await http.post(Uri.parse('$apiBase/auth/register'),headers:{'Content-Type':'application/json'},body:jsonEncode({'full_name':name,'email':email,'password':password})).timeout(const Duration(seconds:12));
    await _saveTokens(r);
  }
  Future<List<Drama>> favorites() async {
    final token=await storage.read(key:'access_token'); if(token==null)return [];
    final r=await http.get(Uri.parse('$apiBase/me/favorites'),headers:{'Authorization':'Bearer $token'}).timeout(const Duration(seconds:12));
    if(r.statusCode!=200) throw Exception('Favoris indisponibles'); return (jsonDecode(r.body) as List).map((e)=>Drama.fromJson(e)).toList();
  }
  Future<List<Map<String,dynamic>>> history() async {
    final token=await storage.read(key:'access_token'); if(token==null)return [];
    final r=await http.get(Uri.parse('$apiBase/me/history'),headers:{'Authorization':'Bearer $token'}).timeout(const Duration(seconds:12));
    if(r.statusCode!=200) throw Exception('Historique indisponible'); return List<Map<String,dynamic>>.from(jsonDecode(r.body));
  }
  Future<void> toggleFavorite(int id,bool add) async {
    final token=await storage.read(key:'access_token'); if(token==null)throw Exception('Connectez-vous pour synchroniser vos favoris.');
    final uri=Uri.parse('$apiBase/me/favorites/$id');
    final r=add?await http.post(uri,headers:{'Authorization':'Bearer $token'}):await http.delete(uri,headers:{'Authorization':'Bearer $token'});
    if(r.statusCode!=204)throw Exception('Impossible de synchroniser ce favori.');
  }
  Future<List<Map<String,dynamic>>> plans() async {
    final r=await http.get(Uri.parse('$apiBase/subscriptions/plans')).timeout(const Duration(seconds:12));
    if(r.statusCode!=200)throw Exception('Offres indisponibles');return List<Map<String,dynamic>>.from(jsonDecode(r.body));
  }
  Future<String> checkout(String planId,String provider,String phone) async {
    final token=await storage.read(key:'access_token');if(token==null)throw Exception('Connectez-vous avant de souscrire.');
    final r=await http.post(Uri.parse('$apiBase/subscriptions/checkout'),headers:{'Authorization':'Bearer $token','Content-Type':'application/json'},body:jsonEncode({'plan_id':planId,'provider':provider,'phone_number':phone.isEmpty?null:phone})).timeout(const Duration(seconds:20));
    if(r.statusCode<200||r.statusCode>=300){final data=jsonDecode(r.body);throw Exception(data['detail']??'Paiement impossible');}
    return jsonDecode(r.body)['checkout_url'] as String;
  }
  Future<void> saveProgress(int episodeId,int seconds) async {
    final token=await storage.read(key:'access_token'); if(token==null)return;
    await http.put(Uri.parse('$apiBase/me/progress'),headers:{'Authorization':'Bearer $token','Content-Type':'application/json'},body:jsonEncode({'episode_id':episodeId,'progress_seconds':seconds,'completed':false})).timeout(const Duration(seconds:8));
  }
  Future<Map<String,dynamic>> stream(int episodeId) async {
    final token=await storage.read(key:'access_token');
    final r=await http.get(Uri.parse('$apiBase/episodes/$episodeId'),headers:{'Authorization':'Bearer $token'}).timeout(const Duration(seconds:12));
    if(r.statusCode!=200) throw Exception('Flux vidéo indisponible'); return jsonDecode(r.body);
  }
}
final api=ApiClient();
