 Future<void> _load({String? preferred})async{try{final stream=await api.stream(widget.episodeId);qualities=List<Map<String,dynamic>>.from(stream['qualities']);if(qualities.isEmpty)throw Exception('Aucune qualité disponible');final chosen=qualities.firstWhere((q)=>q['resolution']==(preferred??'360p'),orElse:()=>qualities.first);final old=controller;final pos=old?.value.position??Duration.zero;final next=VideoPlayerController.networkUrl(Uri.parse(chosen['url']));await next.initialize();if(!mounted){await next.dispose();return;}await next.seekTo(pos);await next.play();await old?.dispose();setState((){controller=next;quality=chosen['resolution'];loading=false;error=null;});}catch(e){if(mounted)setState((){error=e.toString();loading=false;});}}
 @override void dispose(){progressTimer?.cancel();final c=controller;if(c!=null&&c.value.isInitialized){unawaited(api.saveProgress(widget.episodeId,c.value.position.inSeconds));}unawaited(SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]));unawaited(SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge));unawaited(controller?.dispose()??Future<void>.value());super.dispose();}
 @override Widget build(BuildContext context){final c=controller;return Scaffold(backgroundColor:Colors.black,appBar:AppBar(backgroundColor:Colors.black,title:Text('${widget.dramaTitle} · Ép. ${widget.episodeNumber}',style:const TextStyle(fontSize:13)),actions:[if(qualities.isNotEmpty)PopupMenuButton<String>(initialValue:quality,onSelected:(v)=>_load(preferred:v),itemBuilder:(_)=>qualities.map((q)=>PopupMenuItem(value:q['resolution'] as String,child:Text(q['resolution'] as String))).toList(),child:Padding(padding:const EdgeInsets.all(14),child:Text(quality,style:const TextStyle(color:violet))))]),body:Center(child:loading?const CircularProgressIndicator(color:violet):error!=null?Padding(padding:const EdgeInsets.all(24),child:Text('Lecture indisponible. $error',textAlign:TextAlign.center)):c==null?const SizedBox():AspectRatio(aspectRatio:c.value.aspectRatio,child:Stack(alignment:Alignment.center,children:[VideoPlayer(c),IconButton(icon:Icon(c.value.isPlaying?Icons.pause_circle:Icons.play_circle,color:Colors.white,size:58),onPressed:()=>setState(()=>c.value.isPlaying?c.pause():c.play())),Positioned(bottom:0,left:10,right:10,child:VideoProgressIndicator(c,allowScrubbing:true,colors:const VideoProgressColors(playedColor:violet,bufferedColor:Colors.white30,backgroundColor:Colors.white12)))]))));}}
